import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

interface StudyRow {
  label: string;
  controlPoints: number;
  rmsSampled: number;
  unsampledRms: number;
  changeMax: number;
  maxCurvature: number;
  rmsHoldout: number;
}

interface Study {
  cases: Record<string, { rows: StudyRow[]; note: string }>;
}

/** Reads the persisted validation-study evidence (data/validation/study.json,
 *  regenerated by `npm run study`). These assertions are the checkable claims the
 *  workbench makes about complexity, shape cost and unsampled regions — they must
 *  not silently drift. */
function loadStudy(): Study {
  return JSON.parse(readFileSync(resolve(__dirname, '../data/validation/study.json'), 'utf8')) as Study;
}

describe('validation study evidence', () => {
  const study = loadStudy();

  it('clean data fits near the noise floor at every complexity', () => {
    for (const row of study.cases.clean.rows) {
      expect(row.rmsSampled).toBeLessThan(0.002);
      expect(row.rmsHoldout).toBeLessThan(0.002);
    }
  });

  it('a real design fold is recovered better by a C0 crease than by a smooth fit', () => {
    const [smooth, crease] = study.cases.fold.rows;
    expect(smooth.label).toContain('平滑');
    expect(crease.label).toContain('折线');
    expect(crease.rmsSampled).toBeLessThan(smooth.rmsSampled * 0.7);
    expect(crease.changeMax).toBeLessThan(smooth.changeMax * 0.7);
  });

  it('adding control points to chase a spike raises unsampled-region change and shape cost', () => {
    const rows = study.cases.singleRow.rows;
    const base = rows[0];
    const worst = rows[rows.length - 1];
    expect(worst.controlPoints).toBeGreaterThan(base.controlPoints * 2.5);
    expect(worst.changeMax).toBeGreaterThan(base.changeMax);
    expect(worst.maxCurvature).toBeGreaterThan(base.maxCurvature);
  });

  it('a local bump at high complexity costs more shape than the robust baseline', () => {
    const rows = study.cases.bump.rows;
    const base = rows[0];
    const worst = rows[rows.length - 1];
    expect(worst.maxCurvature).toBeGreaterThan(base.maxCurvature);
    expect(worst.changeMax).toBeGreaterThan(base.changeMax);
  });
});
